	public static void setActionStateWithTrigger<T>(MultiStateDockingAction<T> action, T userData,
			EventTrigger trigger) {
		foreach (ActionState<T> actionState in action.getAllActionStates()) {
			if (actionState.getUserData() == userData) {
				action.setCurrentActionStateWithTrigger(actionState, trigger);
				return;
			}
		}
		fail("Invalid action state user data");
	}

